function TrailRankDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        --- 分组信息构造
        while table.count(trailBattleMgr:GetEnterData()) == 0 do
            coroutine.yield()
        end
        --self:FreshSegmentInfo()
        --self:ConstructGroup(trailBattleMgr:GetEnterData())
        GameUtils.Request(Interfaces.TrailRank, {}, function(request, response)
            if checkInt(response.errCode) == 0 then
                local responseData = checkTable(response.data)
                --printInfo("rankData====>>"..table.dump(responseData))
                self.allRank = checkTable(responseData.serverRank)
                if not isNull(self.allRank) then--每个数据里面加上排名顺序
                    for k, v in pairs(self.allRank) do
                        self.allRank[k]["order"] = k
                    end
                end
                self.myRank = checkInt(responseData.playerRank)
                local curSegment = trailBattleMgr:GetMySegment()
                local segmentData = trailBattleMgr:GetSegmentRewardVoByRefId(curSegment)
                self.MySegText.text = segmentData.name
                self.ImgLevel.Status = segmentData.icon
                self.chooseType = FilterType.MY_GROUP
                self:OnClickTabToggleAction()
                if isNull(self.CommonTabToggleUp.Env) then
                    self.CommonTabToggleUp:Init()
                end
                self.CommonTabToggleUp.Env:FillToggles(
                        {
                            [1] = {
                                text = localize("当前分组"),
                                textColor = {
                                    default = Color.New(255/255, 255/255, 255/255, 102/255), --这边有透明度变化，所以传入rgba四个参数的颜色
                                    selected = Color.New(255/255, 255/255, 255/255, 255/255)
                                },
                                fontSize = {
                                    default = 32,
                                    selected = 36
                                },
                                --redPointStrNode = Constants.RedPointConst.DailyBoxTask,
                                func = function()
                                    self.chooseType = FilterType.MY_GROUP
                                    self:OnClickTabToggleAction()
                                end
                            },
                            [2] = {
                                text = localize("最强排行榜"),
                                textColor = {
                                    default = Color.New(255/255, 255/255, 255/255, 102/255), --这边有透明度变化，所以传入rgba四个参数的颜色
                                    selected = Color.New(255/255, 255/255, 255/255, 255/255)
                                },
                                fontSize = {
                                    default = 32,
                                    selected = 36
                                },
                                --redPointStrNode = Constants.RedPointConst.WeeklyBoxTask,
                                func = function()
                                    self.chooseType = FilterType.ALL_RANK
                                    self:OnClickTabToggleAction()
                                end
                            }
                        }
                )

            end
        end)
    end))
    return coWait
end

function TrailRankDialog:OnClickTabToggleAction()
    if self.chooseType == FilterType.MY_GROUP then
        local myData = trailBattleMgr:GetMyRoomRankInfo()
        local myRankEnv = CfUtils.GetLuaScr(self.MyRankingGroup.gameObject, "Game.UI.TrailStage.TrailRankCell")
        myRankEnv:FreshBaseUI(myData)
        self.myItemIndex = myData.order - 1
        KTool.SetActive(self.MyRankingGroup.transform, true)
        KTool.SetActive(self.RightPanel, true)
        KTool.SetActive(self.EmptyNode, false)
        self.data = {}
        self.data = trailBattleMgr:GetEnterData().roomRank
        print("--->>"..table.dump(self.data))
        if not self.ListView.IsListViewInit then
            self.ListView:InitListView(#self.data, Bind(self, self.OnGetItemByIndex))
        else
            GameUtils.ReloadData(self.ListView, #self.data)
        end
        self.ListView.mOnSnapNearestChanged = Bind(self, self.OnListViewSnapTargetChanged)
    elseif self.chooseType == FilterType.ALL_RANK then
        KTool.SetActive(self.MyRankingGroup.transform, false)
        local isNullAllRank = table.count(self.allRank) == 0
        KTool.SetActive(self.RightPanel, not isNullAllRank)
        KTool.SetActive(self.EmptyNode, isNullAllRank)
        if not isNullAllRank then
            self.data = {}
            self.data = clone(self.allRank)
            self.myItemIndex = nil  
            local playerId = GameUtils.GetPlayerId()
            for i, v in pairs(self.data) do
                if checkNumber(v.playerId) == checkNumber(playerId) then
                    self.myItemIndex = i - 1
                end
            end
            --print("--->>"..table.dump(self.data))
            table.insert(self.data, {isLast = true})
            if not self.ListView.IsListViewInit then
                self.ListView:InitListView(#self.data, Bind(self, self.OnGetItemByIndex))
            else
                GameUtils.ReloadData(self.ListView, #self.data)
            end
        end
    end
    --CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.ListView.transform.parent.transform)
end

function TrailRankDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("RankCellNode")
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, "Game.UI.TrailStage.TrailRankCell")
    if nodeEnv then
        local luaIndex = index + 1
        local data = self.data[luaIndex]
        if data.isLast then
            KTool.SetActive(cell, false)
        else
            nodeEnv:FreshBaseUI(data)
            KTool.SetActive(cell, true)
        end
    end
    return cell
end

function TrailRankDialog:OnListViewSnapTargetChanged()
    local isShow
    if isNull(self.myItemIndex) then
        isShow = false
    else
        local myCell = self.ListView:GetShownItemByItemIndex(self.myItemIndex)
        isShow = isNull(myCell)
    end
    KTool.SetActive(self.MyRankingGroup.transform, isShow)
end


function TrailRankDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return TrailRankDialog